module legacy_files;
fn file_read_text(value:i64) -> i64 { return value+1; }
fn file_write_text(value:str) -> str { return value; }
fn identity<T:wire>(value:T) -> T { return unwrap(decode_json<T>(encode_json(value))); }
fn main() -> unit !{io} { print(identity(file_read_text(41))); print(file_write_text("Я🧠")); }
test fn preserved_test() -> unit { assert(file_read_text(41)==42); assert(file_write_text("text")=="text"); }
